# Load required libraries
library(jsonlite)
library(dplyr)

# Function to convert HUMMEL data to JSON
convert_hummel_to_json <- function(data_file, output_file = "hummel_data.json") {
  # Read the HUMMEL management data
  # Adjust read function based on your data format (CSV, Excel, etc.)
  if (grepl("\\.csv$", data_file)) {
    hummel_data <- read.csv(data_file, stringsAsFactors = FALSE)
  } else if (grepl("\\.xlsx$", data_file)) {
    library(readxl)
    hummel_data <- read_excel(data_file)
  } else {
    stop("Unsupported file format. Please provide CSV or Excel file.")
  }

  # Convert to JSON with pretty printing
  json_output <- toJSON(hummel_data, pretty = TRUE, auto_unbox = TRUE)

  # Write to file
  write(json_output, output_file)

  cat("Successfully converted to JSON:", output_file, "\n")
  return(json_output)
}

# Usage example
# convert_hummel_to_json("hummel_management_data.csv", "hummel_data.json")
```

## Advanced Version with Data Validation

```r
# Enhanced script with validation and error handling
convert_hummel_to_json_advanced <- function(data_file, output_file = "hummel_data.json", 
                                           validate = TRUE) {

  # Load libraries
  library(jsonlite)
  library(dplyr)
  library(readxl)

  tryCatch({
    # Read data based on file extension
    if (grepl("\\.csv$", data_file, ignore.case = TRUE)) {
      hummel_data <- read.csv(data_file, stringsAsFactors = FALSE)
    } else if (grepl("\\.xlsx$", data_file, ignore.case = TRUE)) {
      hummel_data <- read_excel(data_file)
    } else {
      stop("File format not supported. Use CSV or Excel.")
    }

    # Data validation
    if (validate) {
      if (nrow(hummel_data) == 0) {
        stop("Data file is empty")
      }

      if (ncol(hummel_data) == 0) {
        stop("Data file has no columns")
      }

      # Check for required HUMMEL fields (adjust based on your schema)
      required_fields <- c("id", "date", "status")  # Example fields
      missing_fields <- setdiff(required_fields, names(hummel_data))
      if (length(missing_fields) > 0) {
        warning(paste("Missing fields:", paste(missing_fields, collapse = ", ")))
      }
    }

    # Convert special characters and handle NA values
    hummel_data[is.na(hummel_data)] <- NULL

    # Convert to JSON with proper formatting
    json_output <- toJSON(
      hummel_data, 
      pretty = TRUE, 
      auto_unbox = TRUE,
      digits = NA,
      na = "null"
    )

    # Write to file
    writeLines(json_output, output_file)

    # Print summary
    cat("✓ Conversion successful!\n")
    cat("  Records:", nrow(hummel_data), "\n")
    cat("  Columns:", ncol(hummel_data), "\n")
    cat("  Output file:", output_file, "\n")

    return(list(
      success = TRUE,
      records = nrow(hummel_data),
      columns = ncol(hummel_data),
      file = output_file
    ))

  }, error = function(e) {
    cat("✗ Error during conversion:", e$message, "\n")
    return(list(success = FALSE, error = e$message))
  })
}

# Usage
# result <- convert_hummel_to_json_advanced("hummel_data.csv", "output.json")
# print(result)
