## Batch Processing Script

```r
# For processing multiple files
batch_convert_hummel <- function(input_directory, output_directory = "./json_output") {
  library(jsonlite)
  library(readxl)

  # Create output directory if it doesn't exist
  if (!dir.exists(output_directory)) {
    dir.create(output_directory)
  }

  # Get all CSV and Excel files
  files <- list.files(input_directory, 
                      pattern = "\\.(csv|xlsx|xls)$", 
                      full.names = TRUE,
                      ignore.case = TRUE)

  results <- list()

  for (file in files) {
    tryCatch({
      # Extract filename without extension
      base_name <- tools::file_path_sans_ext(basename(file))
      output_file <- file.path(output_directory, paste0(base_name, ".json"))

      # Convert file
      if (grepl("\\.csv$", file, ignore.case = TRUE)) {
        data <- read.csv(file, stringsAsFactors = FALSE)
      } else {
        data <- read_excel(file)
      }

      # Convert to JSON
      json_data <- toJSON(data, pretty = TRUE, auto_unbox = TRUE)
      writeLines(json_data, output_file)

      results[[base_name]] <- list(
        status = "success",
        records = nrow(data),
        output = output_file
      )

      cat("✓ Converted:", base_name, "\n")

    }, error = function(e) {
      results[[basename(file)]] <- list(
        status = "failed",
        error = e$message
      )
      cat("✗ Failed:", basename(file), "-", e$message, "\n")
    })
  }

  return(results)
}

# Usage
# results <- batch_convert_hummel("./input_data", "./json_output")
